function z({registerIndicator:M,sourceValues:k,nulls:c}){M({id:"oa-apz",name:"Adaptive Price Zone",category:"Channels",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:20,min:1,max:5e3,step:1},{key:"bandPct",type:"number",label:"Band Multiplier",default:2,min:.001,max:100,step:.1,tooltip:"Band distance as a multiple of the double smoothed bar range."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"middle",type:"line",title:"Middle",style:{color:"#ffeb3b",lineWidth:2}},{key:"upper",type:"line",title:"Upper",style:{color:"#ffeb3b",lineWidth:1}},{key:"lower",type:"line",title:"Lower",style:{color:"#ffeb3b",lineWidth:1}}],fills:[{between:["upper","lower"],colorUp:"#ffeb3b",colorDown:"#ffeb3b",opacity:.1}],calc(t,p){const x=Math.min(5e3,Math.max(1,Math.floor(Number(p.period)||20))),A=Math.max(.001,Number(p.bandPct)||2),s=k(t,p.source??"close"),l=2/(Math.sqrt(x)+1),o=1-l,u=new Array(t.length).fill(NaN),b=new Array(t.length).fill(NaN),f=new Array(t.length).fill(NaN);let d=0,a=0,m=0,n=0,r=1,h=!0;for(let e=0;e<t.length;e++){const y=t[e],R=Number.isFinite(s[e])?s[e]:0,w=y.high-y.low,W=Number.isFinite(w)?w:0;d=l*R+o*d,a=l*d+o*a,m=l*W+o*m,n=l*m+o*n;let i=a,g=n;if(h){r*=o*o;const P=1-r!==0?1/(1-r):1;i=P*a,g=P*n,h=r>1e-10}const N=A*g;u[e]=i,b[e]=i+N,f[e]=i-N}return{middle:c(u),upper:c(b),lower:c(f)}}})}export{z as default};
